  run Q checkout-ref
  [ "$status" -eq 0 ]
  [ "$output" = "actions/checkout@v4" ]
}

@test "workflow sets least-privilege permissions (contents: read)" {
  run Q permissions
  [ "$status" -eq 0 ]
  [ "$output" = "read" ]
}

